def fs(v,a,hc,b):
	sm=0
	for c in range(hc,hc+b):
		sm+=sum(v[c][:a])
	return sm

def sp(v,wc,hc,b):
	sm=0
	for c in range(hc,hc+b):
		sm+=v[c][wc]
	return sm

def gm(sm,ms):
	if sm<ms:
		ms=sm
	return ms

def isn(ms):
	return ms==0

def sq(v,h,w,a,b,ms):
	#print('h-b',list(range(h-b+1)))
	#print('w-a',list(range(w-a)))
	if isn(ms):
		return 0
	for d in range(h-b+1):
		sm=fs(v,a,d,b)
		#print('f>> z={} x={} sum={}'.format(d,0,sm))
		ms=gm(sm,ms)
		for c in range(w-a):
			sm-=sp(v,c,d,b)
			sm+=sp(v,c+a,d,b)			
			#print('c>> z={} x={} sum={}'.format(d,c+1,sm))
			ms=gm(sm,ms)
			if isn(ms):
				return 0
	return ms

